<template>
  <div ref="pageRef" class="spectacle-page" :class="{ 'perf-lite': liteMode, 'theme-light': themeMode === 'light' }">
    <canvas ref="particleCanvas" class="particle-layer" aria-hidden="true" />
    <div class="spotlight" aria-hidden="true" />
    <header class="hero glass-surface">
      <div><h1>日志记录</h1><p>搜索、筛选并进入每一条日志的分析上下文。</p></div>
      <div class="hero-actions"><button class="icon-button" type="button" aria-label="刷新日志" @click="load"><el-icon :class="{ spin: loading }"><Refresh /></el-icon></button><button class="primary-button" type="button" @click="router.push('/upload')"><el-icon><Upload /></el-icon>上传日志</button></div>
    </header>

    <section class="kpi-grid" aria-label="日志概览"><article v-for="(item, index) in kpis" :key="item.label" class="kpi-card glass-surface" :style="{ '--stagger': `${index * 70}ms` }"><div class="kpi-mark" :class="item.tone"><el-icon><component :is="item.icon" /></el-icon></div><div><span>{{ item.label }}</span><strong class="mono">{{ item.display }}</strong></div><div class="mini-bars" aria-hidden="true"><i v-for="bar in 5" :key="bar" :style="{ height: `${8 + ((index + bar) % 4) * 4}px` }" /></div></article></section>

    <main class="workspace-card glass-surface">
      <div class="filter-deck"><div class="search-box"><el-icon><Search /></el-icon><el-input v-model="keyword" clearable placeholder="搜索文件名、版本、记录 ID" /></div><el-select v-model="project" clearable filterable placeholder="全部项目"><el-option v-for="name in projects" :key="name" :label="name" :value="name" /></el-select><el-select v-model="sourceType" aria-label="日志来源"><el-option v-for="option in sourceOptions" :key="option.value" :label="option.label" :value="option.value" /></el-select><el-date-picker v-model="dateRange" type="daterange" unlink-panels range-separator="至" start-placeholder="开始日期" end-placeholder="结束日期" /><el-select v-model="sortBy" aria-label="排序"><el-option label="最新上传" value="created_desc" /><el-option label="最早上传" value="created_asc" /><el-option label="文件最大" value="size_desc" /><el-option label="错误最多" value="errors_desc" /></el-select></div>
      <div class="filter-tabs"><div class="segmented"><button v-for="option in statusOptions" :key="option.value" type="button" :class="{ active: status === option.value }" @click="status = option.value">{{ option.label }}</button></div><button v-if="hasFilters" class="clear-button" type="button" @click="clearFilters">清空筛选</button></div>

      <div v-if="selectedRecords.length" class="batch-strip glass-elevated"><span><el-icon><Select /></el-icon>已选择 {{ selectedRecords.length }} 条 <em>{{ formatSize(selectedSize) }}</em></span><div><button type="button" @click="selectAllFiltered">全选结果</button><button type="button" @click="clearSelection">取消</button><button class="danger-button" type="button" @click="removeSelected">批量删除</button></div></div>
      <div class="table-heading"><div><span class="kicker">LIVE DATASET</span><strong>日志列表</strong></div><span>显示 {{ filtered.length }} 条 <i v-if="lastUpdated">· {{ lastUpdated }}</i></span></div>

      <div v-if="loading && !records.length" class="skeleton-grid"><i v-for="row in 8" :key="row" /></div>
      <el-table v-else class="log-table" :data="paged" row-key="id" @row-click="previewRecord">
        <el-table-column width="52" align="center"><template #header><el-checkbox :model-value="pageSelected" :indeterminate="pagePartiallySelected" aria-label="选择当前页" @change="togglePageSelection" /></template><template #default="scope"><el-checkbox :model-value="selectedIds.has(scope.row.id)" :disabled="!scope.row.task_id || scope.row.source_type === 'collector'" :aria-label="`选择 ${recordTitle(scope.row)}`" @click.stop @change="(checked) => toggleSelection(scope.row, checked)" /></template></el-table-column>
        <el-table-column label="记录" min-width="190"><template #default="scope"><div class="file-entry"><span class="file-glyph"><el-icon><Document /></el-icon></span><div><strong v-html="highlightText(recordTitle(scope.row))" /><small v-if="scope.row.source_type === 'collector'">采集端记录</small></div></div></template></el-table-column>
        <el-table-column label="来源" width="110"><template #default="scope"><span class="source-chip" :class="scope.row.source_type">{{ sourceLabel(scope.row.source_type) }}</span></template></el-table-column>
        <el-table-column label="上传人" min-width="132"><template #default="scope"><div class="stacked"><strong>{{ scope.row.uploader_name || '-' }}</strong></div></template></el-table-column>
        <el-table-column label="项目 / 版本" min-width="132"><template #default="scope"><div class="stacked"><strong>{{ scope.row.project_name || '-' }}</strong><small>{{ scope.row.version || '未填写版本' }}</small></div></template></el-table-column>
        <el-table-column label="状态" width="104"><template #default="scope"><span class="level-chip" :class="scope.row.statusKey"><i />{{ statusMeta[scope.row.statusKey].label }}</span></template></el-table-column>
        <el-table-column label="内容 / 结果" min-width="154"><template #default="scope"><div class="stacked"><strong><template v-if="scope.row.source_type === 'collector'">{{ scope.row.batch_count || 0 }} 批次 · </template>{{ scope.row.file_count || 0 }} 文件 · {{ formatSize(scope.row.original_size) }}</strong><small><b class="error">{{ scope.row.error_count || 0 }} 错误</b><b class="warning">{{ scope.row.warning_count || 0 }} 警告</b></small></div></template></el-table-column>
        <el-table-column label="采集 / 上传时间" min-width="154"><template #default="scope"><time class="mono">{{ formatDate(scope.row.created_at) }}</time></template></el-table-column>
        <el-table-column label="操作" width="156" fixed="right" align="center"><template #default="scope"><div class="row-actions" @click.stop><button type="button" aria-label="预览日志内容" title="预览日志内容" @click="previewRecord(scope.row)"><el-icon><Document /></el-icon></button><button type="button" aria-label="查看分析" title="查看分析" @click="viewTask(scope.row)"><el-icon><View /></el-icon></button><button v-if="scope.row.source_type !== 'collector'" class="delete" type="button" aria-label="删除日志" title="删除日志" @click="remove(scope.row)"><el-icon><Delete /></el-icon></button></div></template></el-table-column>
        <template #empty><div class="empty-state"><el-icon><Document /></el-icon><strong>没有符合条件的记录</strong></div></template>
      </el-table>
      <footer v-if="filtered.length"><span>共 {{ filtered.length }} 条记录</span><el-pagination v-model:current-page="page" :page-size="pageSize" :total="filtered.length" :pager-count="5" layout="prev, pager, next" /></footer>
    </main>

    <el-drawer v-model="detailOpen" direction="rtl" size="min(760px, 92vw)" class="detail-drawer" :with-header="false"><div v-if="preview" class="detail-pane"><div class="detail-top"><span class="kicker">日志内容预览</span><button class="icon-button" aria-label="关闭详情" @click="detailOpen = false">×</button></div><h2>{{ recordTitle(preview) }}</h2><div class="detail-badges"><span class="source-chip" :class="preview.source_type">{{ sourceLabel(preview.source_type) }}</span><span class="level-chip" :class="preview.statusKey"><i />{{ statusMeta[preview.statusKey].label }}</span></div><dl><div><dt>项目</dt><dd>{{ preview.project_name || '-' }}</dd></div><div><dt>版本</dt><dd>{{ preview.version || '-' }}</dd></div><div><dt>测试任务</dt><dd>{{ preview.test_task_name || '-' }}</dd></div><div><dt>采集 / 上传人</dt><dd>{{ preview.uploader_name || '-' }}{{ preview.uploader_email ? ' · ' + preview.uploader_email : '' }}</dd></div><div><dt>批次 / 文件</dt><dd>{{ preview.batch_count || 1 }} / {{ preview.file_count || 0 }}</dd></div><div><dt>时间</dt><dd>{{ formatDate(preview.created_at) }}</dd></div></dl><div class="preview-controls"><el-select v-if="previewBatches.length > 1" v-model="previewBatchId" aria-label="上传批次" @change="loadPreviewBatch"><el-option v-for="batch in previewBatches" :key="batch.id" :label="`第 ${batch.upload_position || 1} 次上传 · ${batch.original_name || batch.id}`" :value="batch.id" /></el-select><el-select v-if="previewFiles.length > 1" v-model="previewFileId" aria-label="日志文件" @change="loadPreviewFile"><el-option v-for="file in previewFiles" :key="file.id" :label="file.relative_path" :value="String(file.id)" /></el-select></div><div class="download-row"><button type="button" @click="downloadCurrent('original')">原始包</button><button type="button" @click="downloadCurrent('batch')">解析包</button><button type="button" @click="downloadCurrent('results')">结果包</button></div><div class="raw-preview" :class="{ loading: previewLoading }"><div class="raw-preview-heading"><strong>{{ previewContent.relative_path || '日志内容' }}</strong><span v-if="previewContent.truncated">仅展示前 500 行</span></div><pre v-if="previewContent.lines?.length">{{ previewContent.lines.join('\n') }}</pre><div v-else class="preview-empty">{{ previewLoading ? '正在读取日志内容…' : '该文件没有可预览内容' }}</div></div><div class="log-search"><div><el-input v-model="rawSearchKeyword" clearable placeholder="在原始日志中全文搜索" @keyup.enter="searchCurrentLog" /><el-button type="primary" :loading="rawSearchLoading" @click="searchCurrentLog">搜索</el-button></div><p v-if="rawSearchTotal">找到 {{ rawSearchTotal }} 条命中</p><button v-for="item in rawSearchResults" :key="`${item.file_id}-${item.line_number}`" type="button" @click="openSearchHit(item)"><strong>{{ item.relative_path }} · 第 {{ item.line_number }} 行</strong><span>{{ item.content }}</span></button></div><div class="detail-actions"><button class="primary-button" type="button" @click="viewTask(preview)">打开当前批次分析</button><button v-if="preview.source_type !== 'collector'" class="danger-button" type="button" @click="remove(preview)">删除</button></div></div></el-drawer>
  </div>
</template>

<script setup>
import { computed, markRaw, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { DataLine, Delete, Document, Files, FolderOpened, Refresh, Search, Select, Upload, View } from '@element-plus/icons-vue'
import { downloadLog, getLogDetail, getLogPreview, getLogs, getProjects, searchLog } from '@/api/log'
import { deleteTask } from '@/api/task'
import { useTheme } from '@/utils/theme'

const router = useRouter(); const pageRef = ref(null); const particleCanvas = ref(null); const records = ref([]); const projects = ref([]); const loading = ref(false); const keyword = ref(''); const project = ref(''); const sourceType = ref('all'); const status = ref('all'); const dateRange = ref([]); const sortBy = ref('created_desc'); const page = ref(1); const pageSize = 12; const lastUpdated = ref(''); const selectedIds = ref(new Set()); const batchDeleting = ref(false); const detailOpen = ref(false); const preview = ref(null); const previewBatchId = ref(''); const previewFileId = ref(''); const previewFiles = ref([]); const previewContent = ref({ lines: [] }); const previewLoading = ref(false); const rawSearchKeyword = ref(''); const rawSearchLoading = ref(false); const rawSearchResults = ref([]); const rawSearchTotal = ref(0); const liteMode = ref(false)
const { themeMode } = useTheme()
const statusMeta = { uploading: { label: '上传中', group: 'active' }, queued: { label: '排队中', group: 'active' }, parsing: { label: '解析中', group: 'active' }, completed: { label: '已完成', group: 'completed' }, failed: { label: '失败', group: 'failed' }, unknown: { label: '未知', group: 'active' } }; const statusOptions = [{ label: '全部', value: 'all' }, { label: '处理中', value: 'active' }, { label: '已完成', value: 'completed' }, { label: '失败', value: 'failed' }]
const sourceOptions = [{ label: '全部来源', value: 'all' }, { label: '采集日志', value: 'collector' }, { label: '自己上传', value: 'uploaded' }]
const sourceLabel = (value) => value === 'collector' ? '采集日志' : '自己上传'
const normalizeRecord = (item) => ({ ...item, statusKey: statusMeta[item.status] ? item.status : 'unknown' }); const formatSize = (bytes) => { if (!bytes) return '0 B'; const units = ['B', 'KB', 'MB', 'GB']; const i = Math.min(Math.floor(Math.log(bytes) / Math.log(1024)), 3); return `${(bytes / 1024 ** i).toFixed(i ? 1 : 0)} ${units[i]}` }; const formatDate = (value) => value ? new Date(value).toLocaleString('zh-CN', { hour12: false }) : '-'
const recordTitle = (record) => record?.source_type === 'collector' ? (record.test_task_name || `${record.project_name || '未命名项目'}采集任务`) : (record?.original_name || '-')
const previewBatches = computed(() => preview.value?.batches || (preview.value ? [preview.value] : []))
function collectorStatus(batches) { if (batches.some((item) => item.status === 'failed')) return 'failed'; if (batches.length && batches.every((item) => item.status === 'completed')) return 'completed'; if (batches.some((item) => item.status === 'parsing')) return 'parsing'; if (batches.some((item) => item.status === 'queued')) return 'queued'; return 'uploading' }
function groupRecords(items) { const grouped = new Map(); const result = []; items.map(normalizeRecord).forEach((item) => { if (item.source_type !== 'collector') { result.push(item); return }; const key = item.upload_session_id || item.query_code || item.id; let group = grouped.get(key); if (!group) { group = { ...item, id: `collector:${key}`, record_kind: 'collector_session', original_name: '', batches: [], batch_count: 0, file_count: 0, total_files: 0, processed_files: 0, original_size: 0, total_bytes: 0, processed_bytes: 0, total_lines: 0, error_count: 0, warning_count: 0 }; grouped.set(key, group); result.push(group) }; group.batches.push(item); group.batch_count += 1; ['file_count','total_files','processed_files','original_size','total_bytes','processed_bytes','total_lines','error_count','warning_count'].forEach((field) => { group[field] += Number(item[field] || 0) }); if (new Date(item.created_at) < new Date(group.created_at)) group.created_at = item.created_at; if (new Date(item.updated_at) > new Date(group.updated_at)) group.updated_at = item.updated_at }); grouped.forEach((group) => { group.batches.sort((a, b) => (a.upload_position || 0) - (b.upload_position || 0)); const latest = group.batches[group.batches.length - 1]; group.task_id = latest?.task_id || ''; group.status = collectorStatus(group.batches); group.statusKey = statusMeta[group.status] ? group.status : 'unknown' }); return result }
const totals = computed(() => { const set = new Set(records.value.map((item) => item.project_name).filter(Boolean)); return records.value.reduce((sum, item) => ({ files: sum.files + (item.file_count || 0), size: sum.size + (item.original_size || 0), projects: set.size }), { files: 0, size: 0, projects: set.size }) }); const kpiBase = computed(() => [{ label: '上传记录', value: records.value.length, tone: 'cyan', icon: markRaw(DataLine) }, { label: '日志文件', value: totals.value.files, tone: 'violet', icon: markRaw(Files) }, { label: '占用空间', value: totals.value.size, tone: 'green', icon: markRaw(Document) }, { label: '关联项目', value: totals.value.projects, tone: 'amber', icon: markRaw(FolderOpened) }]); const animated = ref([0, 0, 0, 0]); const kpis = computed(() => kpiBase.value.map((item, index) => ({ ...item, display: index === 2 ? formatSize(animated.value[index]) : animated.value[index].toLocaleString() })))
const filtered = computed(() => { const text = keyword.value.trim().toLowerCase(); const start = dateRange.value?.[0] ? new Date(dateRange.value[0]).setHours(0, 0, 0, 0) : 0; const end = dateRange.value?.[1] ? new Date(dateRange.value[1]).setHours(23, 59, 59, 999) : Infinity; const result = records.value.filter((item) => (!text || `${recordTitle(item)}${item.project_name}${item.version}${item.uploader_name}${item.test_task_name}${item.id}`.toLowerCase().includes(text)) && (!project.value || item.project_name === project.value) && (sourceType.value === 'all' || item.source_type === sourceType.value) && (status.value === 'all' || statusMeta[item.statusKey].group === status.value) && new Date(item.created_at || 0).getTime() >= start && new Date(item.created_at || 0).getTime() <= end); return result.sort((a, b) => sortBy.value === 'created_asc' ? new Date(a.created_at) - new Date(b.created_at) : sortBy.value === 'size_desc' ? (b.original_size || 0) - (a.original_size || 0) : sortBy.value === 'errors_desc' ? (b.error_count || 0) - (a.error_count || 0) : new Date(b.created_at) - new Date(a.created_at) ) }); const paged = computed(() => filtered.value.slice((page.value - 1) * pageSize, page.value * pageSize)); const hasFilters = computed(() => Boolean(keyword.value.trim() || project.value || sourceType.value !== 'all' || status.value !== 'all' || dateRange.value?.length)); const selectedRecords = computed(() => records.value.filter((item) => selectedIds.value.has(item.id))); const selectedSize = computed(() => selectedRecords.value.reduce((sum, item) => sum + (item.original_size || 0), 0)); const selectableOnPage = computed(() => paged.value.filter((item) => item.task_id && item.source_type !== 'collector')); const pageSelected = computed(() => Boolean(selectableOnPage.value.length) && selectableOnPage.value.every((item) => selectedIds.value.has(item.id))); const pagePartiallySelected = computed(() => !pageSelected.value && selectableOnPage.value.some((item) => selectedIds.value.has(item.id)))
const highlightText = (value) => { const escaped = String(value).replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char])); const query = keyword.value.trim(); if (!query) return escaped; const safe = query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); return escaped.replace(new RegExp(`(${safe})`, 'ig'), '<mark>$1</mark>') }
function clearFilters() { keyword.value = ''; project.value = ''; sourceType.value = 'all'; status.value = 'all'; dateRange.value = []; sortBy.value = 'created_desc' }; function toggleSelection(record, checked) { const next = new Set(selectedIds.value); if (checked && record.task_id && record.source_type !== 'collector') next.add(record.id); else next.delete(record.id); selectedIds.value = next }; function togglePageSelection(checked) { const next = new Set(selectedIds.value); selectableOnPage.value.forEach((item) => checked ? next.add(item.id) : next.delete(item.id)); selectedIds.value = next }; function selectAllFiltered() { selectedIds.value = new Set(filtered.value.filter((item) => item.task_id && item.source_type !== 'collector').map((item) => item.id)) }; function clearSelection() { selectedIds.value = new Set() }
const viewTask = (record) => { const selectedBatch = preview.value?.id === record?.id ? record.batches?.find((item) => item.id === previewBatchId.value) : null; const batch = record?.source_type === 'collector' ? selectedBatch || record.batches?.at(-1) : record; if (!batch?.task_id) return ElMessage.warning('该记录没有关联任务'); router.push({ name: 'TaskDetail', params: { taskId: batch.task_id } }) }
async function previewRecord(record) { preview.value = record; detailOpen.value = true; const batch = record.batches?.at(-1) || record; previewBatchId.value = batch.id; await loadPreviewBatch(batch.id) }
async function loadPreviewBatch(uploadID) { previewLoading.value = true; previewContent.value = { lines: [] }; rawSearchResults.value = []; rawSearchTotal.value = 0; try { const detail = await getLogDetail(uploadID); previewFiles.value = detail.files || []; previewFileId.value = previewFiles.value[0] ? String(previewFiles.value[0].id) : ''; if (previewFileId.value) await loadPreviewFile(previewFileId.value) } catch { previewFiles.value = []; ElMessage.error('日志内容加载失败') } finally { previewLoading.value = false } }
async function loadPreviewFile(fileID) { if (!previewBatchId.value || !fileID) return; previewLoading.value = true; try { previewContent.value = await getLogPreview(previewBatchId.value, fileID) } catch { previewContent.value = { lines: [] }; ElMessage.error('日志内容读取失败') } finally { previewLoading.value = false } }
async function downloadCurrent(type) { if (!previewBatchId.value) return; try { const response = await downloadLog(previewBatchId.value, { type }); const link = document.createElement('a'); link.href = URL.createObjectURL(new Blob([response])); link.download = `${recordTitle(preview.value)}-${type}.zip`; link.click(); URL.revokeObjectURL(link.href) } catch { ElMessage.error('下载失败，请稍后重试') } }
async function searchCurrentLog() { const value = rawSearchKeyword.value.trim(); if (!previewBatchId.value || !value) return; rawSearchLoading.value = true; try { const data = await searchLog(previewBatchId.value, { keyword: value, file_id: previewFileId.value || undefined, page: 1, page_size: 50 }); rawSearchResults.value = data.list || []; rawSearchTotal.value = Number(data.total || 0) } catch { ElMessage.error('日志全文搜索失败') } finally { rawSearchLoading.value = false } }
async function openSearchHit(item) { previewFileId.value = String(item.file_id); await loadPreviewFile(previewFileId.value) }
async function load() { if (loading.value) return; loading.value = true; try { const first = await getLogs({ page: 1, page_size: 200 }); const pages = Math.ceil((first.total || 0) / 200); const rest = pages > 1 ? await Promise.all(Array.from({ length: pages - 1 }, (_, i) => getLogs({ page: i + 2, page_size: 200 }))) : []; records.value = groupRecords([first, ...rest].flatMap((data) => data.list || [])); selectedIds.value = new Set([...selectedIds.value].filter((id) => records.value.some((item) => item.id === id))); lastUpdated.value = new Date().toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit', hour12: false }); animateKpis() } catch { ElMessage.error('日志加载失败，请稍后重试') } finally { loading.value = false } }
async function loadProjects() { try { projects.value = await getProjects() || [] } catch { projects.value = [] } }; async function remove(record) { if (record.source_type === 'collector') return; try { await ElMessageBox.confirm(`将永久删除“${record.original_name}”及其分析结果。`, '删除日志记录', { type: 'warning', customClass: 'log-delete-dialog', confirmButtonText: '确认删除', cancelButtonText: '取消' }); await deleteTask(record.task_id); records.value = records.value.filter((item) => item.id !== record.id); detailOpen.value = false; ElMessage.success('日志记录已删除') } catch (error) { if (error !== 'cancel' && error !== 'close') ElMessage.error('删除失败，请稍后重试') } }; async function removeSelected() { if (!selectedRecords.value.length || batchDeleting.value) return; try { await ElMessageBox.confirm(`将永久删除选中的 ${selectedRecords.value.length} 条记录。`, '批量删除日志', { type: 'warning', customClass: 'log-delete-dialog', confirmButtonText: '确认删除', cancelButtonText: '取消' }); batchDeleting.value = true; const targets = selectedRecords.value.filter((item) => item.source_type !== 'collector'); const results = await Promise.allSettled(targets.map((item) => deleteTask(item.task_id))); const deleted = new Set(targets.filter((_, i) => results[i].status === 'fulfilled').map((item) => item.id)); records.value = records.value.filter((item) => !deleted.has(item.id)); clearSelection(); ElMessage.success(`已删除 ${deleted.size} 条记录`) } catch (error) { if (error !== 'cancel' && error !== 'close') ElMessage.error('批量删除失败') } finally { batchDeleting.value = false } }
let rafId = 0; function animateKpis() { cancelAnimationFrame(rafId); const start = performance.now(); const from = [...animated.value]; const to = kpiBase.value.map((item) => item.value); const tick = (now) => { const progress = Math.min((now - start) / 900, 1); const eased = 1 - Math.pow(1 - progress, 3); animated.value = to.map((value, index) => Math.round(from[index] + (value - from[index]) * eased)); if (progress < 1) rafId = requestAnimationFrame(tick) }; rafId = requestAnimationFrame(tick) }
